function uploadProof(file,form){
  if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>10*1024*1024)throw new Error('Use a PNG, JPEG, WebP or GIF image under 10 MB.');
  return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','https://api.cloudinary.com/v1_1/dohlemsrz/image/upload');xhr.timeout=90000;const progress=form.querySelector('[type=submit]');xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.textContent=`Uploading ${Math.round(e.loaded/e.total*100)}%`;};xhr.onerror=xhr.ontimeout=()=>reject(new Error('Proof upload failed. Please retry.'));xhr.onload=()=>{try{const result=JSON.parse(xhr.responseText);if(xhr.status>=400||!safeUrl(result.secure_url))throw new Error('Proof upload was rejected. Please retry.');resolve(result.secure_url);}catch(e){reject(e);}};const body=new FormData();body.append('file',file);body.append('upload_preset','visionflow');xhr.send(body);});
}
