function termsHtml(t){return `<div class="agreement"><h3>${esc(t.projectName)}</h3><p>${t.totalItems} deliverables · ${money(t.rate)} each · Budget ${money(t.budget)}</p><p class="prewrap">${esc(t.scope)}</p><p class="prewrap">${esc(t.terms)}</p><p>Target: ${esc(t.deadline||'Not set')} · Weekly target: ${t.weeklyTarget||'Not set'}</p><p class="prewrap">${esc(t.milestoneText)}</p></div>`;}
function openSignature(){const terms=agreementTerms(project());modal('Review and sign','Your signature records these project terms and the signing time.',`${termsHtml(terms)}${field('Full name','name','','text','required maxlength="200"')}<canvas id="signatureCanvas" class="signature-pad" aria-label="Draw your signature with mouse or touch"></canvas>${button('Clear signature','clear-signature')}<label><input type="checkbox" name="agree" required> I have reviewed these details and agree to this project record.</label>`,async data=>{if(!pad?.drawn)throw new Error('Please draw your signature before submitting.');const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(terms)))),v=>v.toString(16).padStart(2,'0')).join('');await setDoc(doc(db,'portal_public',state.token,'sigs',uid('signature')),{projectKey:state.projectKey,name:text(data.get('name')),image:pad.canvas.toDataURL('image/png'),signedAt:now(),userAgent:navigator.userAgent,termsSnapshot:terms,termsDigest:digest});notify('Signature saved');finishModal();},'Save signature');initPad();}
function initPad(){const canvas=$('signatureCanvas');const rect=canvas.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=rect.width*ratio;canvas.height=180*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.strokeStyle='#167aa6';ctx.lineWidth=2.4;ctx.lineCap='round';pad={canvas,ctx,drawn:false};let drawing=false;const pt=e=>{const b=canvas.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top};};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=pt(e);ctx.beginPath();ctx.moveTo(p.x,p.y);};canvas.onpointermove=e=>{if(!drawing)return;const p=pt(e);ctx.lineTo(p.x,p.y);ctx.stroke();pad.drawn=true;};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;}
function openSignatureReview(id){requireAdmin();const draft=clone(client()),s=projectSigs().find(s=>s.id===id);if(!s)return;const r=sigReview(s);modal('Manage signature',`Signed ${dateText(s.signedAt)}`,`${field('Signer display name','displayName',r.displayName||s.name,'text','required maxlength="200"')}${select('Review state','state',[['pending','Awaiting verification'],['verified','Verified'],['void','Void / request replacement']],r.state||'pending')}${area('Note visible to client','message',r.message||'','maxlength="2000"')}${button('Move signature to bin','archive-signature',`data-id="${esc(id)}"`,'danger')}`,async data=>{const c=clone(draft);c.signatureReviews[id]={state:text(data.get('state')),displayName:text(data.get('displayName')),message:text(data.get('message')),updatedAt:now()};await saveClient(c,'Signature updated');finishModal();});}

function trashEntry(c,kind,label,value,projectKey=state.projectKey,extra={}){const id=uid('trash');c.trash[id]={kind,label,value:clone(value),projectKey:projectKey||'',deletedAt:now(),...extra};return id;}
async function archive(kind,source){
  requireAdmin();const c=clone(client()),p=c.projects[state.projectKey],ops=[];
  if(kind==='client'){c._deleted=true;await saveClient(c,'Client moved to recycle bin');state.clientKey=null;state.projectKey=null;return;}
  if(kind==='project'){const approvalIds=new Set(p.approvals.map(a=>a.id));const records=(await allRecords(c.accessToken)).filter(r=>r.projectKey===state.projectKey||(r.collection==='sigs'&&r.id===state.projectKey)||(r.collection==='confirms'&&approvalIds.has(r.id)));const reviews={signatureReviews:{},feedbackReviews:{}};for(const r of records){const map=r.collection==='sigs'?'signatureReviews':'feedbackReviews';if(c[map][r.id]){reviews[map][r.id]=c[map][r.id];delete c[map][r.id];}}trashEntry(c,kind,p.name,p,state.projectKey,{records,reviews});for(const r of records)ops.push({path:[r.collection,r.id],delete:true});delete c.projects[state.projectKey];}
  if(kind==='payment'||kind==='approval'){const list=kind==='payment'?p.payments:p.approvals;const index=list.findIndex(x=>x.id===source.dataset.id);if(index<0)throw new Error('Record not found.');const value=list[index];const conf=kind==='approval'?confirmation(value):null;trashEntry(c,kind,kind==='payment'?`${money(value.amount)} payment`:value.title,value,state.projectKey,conf?{records:[conf]}:{});if(conf)ops.push({path:['confirms',conf.id],delete:true});list.splice(index,1);}
  if(kind==='item'){const item=p.items.find(i=>Number(i.n)===Number(source.dataset.number));item.deleted=true;item.deletedAt=now();p.totalItems=itemsOf(p).length;}
  if(kind==='signature'||kind==='feedback'){const record=kind==='signature'?projectSigs().find(s=>s.id===source.dataset.id):requests().find(r=>r.id===source.dataset.id&&r.collection===source.dataset.collection);if(!record)throw new Error('Record not found.');const reviews=kind==='signature'?c.signatureReviews:c.feedbackReviews;trashEntry(c,kind,kind==='signature'?record.name:record.message,record,state.projectKey,{review:reviews[record.id]||{}});ops.push({path:[record.collection,record.id],delete:true});delete reviews[record.id];}
  await saveClient(c,'Moved to recycle bin',ops);if(kind==='project')state.projectKey=null;if(!$('modalLayer').hidden)finishModal();
}
function renderTrash(){
  const entries=[];for(const [key,c] of Object.entries(state.clients)){if(c._deleted)entries.push(`<div class="list-row"><strong>${esc(c.name)} · Client workspace</strong><p>Private link disabled while in recycle bin.</p><div class="actions">${button('Restore client','restore-client',`data-client="${esc(key)}"`)}${button('Permanently delete','purge-client',`data-client="${esc(key)}"`,'danger')}</div></div>`);else for(const [id,t] of Object.entries(c.trash||{}))entries.push(`<div class="list-row"><strong>${esc(c.name)} · ${esc(t.kind)} · ${esc(t.label).slice(0,180)}</strong><p>${esc(dateText(t.deletedAt))}</p><div class="actions">${button('Restore','restore-trash',`data-client="${esc(key)}" data-id="${esc(id)}"`)}${button('Permanently delete','purge-trash',`data-client="${esc(key)}" data-id="${esc(id)}"`,'danger')}</div></div>`);}
  $('view').innerHTML=`<section class="hero"><p class="eyebrow">Administrator recovery</p><h1>Recycle bin</h1><p>Restore removed records here. Permanently deleted records cannot be restored.</p>${button('Back to dashboard','dashboard')}</section><section class="panel" style="margin-top:18px">${entries.join('')||'<p class="muted">The recycle bin is empty.</p>'}</section>`;
}
async function restoreTrash(key,id){const c=clone(state.clients[key]),t=c.trash[id],ops=[];if(!t)throw new Error('This record is no longer in the bin.');if(t.kind==='project'){if(c.projects[t.projectKey])throw new Error('A project already uses this label. Rename/remove it before restoring.');c.projects[t.projectKey]=t.value;}else{const p=c.projects[t.projectKey];if(!p)throw new Error('Restore the parent project first.');if(t.kind==='payment'||t.kind==='approval')p[t.kind==='payment'?'payments':'approvals'].push(t.value);if(t.kind==='signature'||t.kind==='feedback'){const {id:recordId,collection:col,...data}=t.value;ops.push({path:[col,recordId],data});c[t.kind==='signature'?'signatureReviews':'feedbackReviews'][recordId]=t.review||{};}}
  for(const map of ['signatureReviews','feedbackReviews'])Object.assign(c[map],t.reviews?.[map]||{});
  for(const record of t.records||[]){const {id:recordId,collection:col,...data}=record;ops.push({path:[col,recordId],data});}delete c.trash[id];await saveClient(c,'Record restored',ops);
}
