async function allRecords(accessToken){const groups=await Promise.all(['sigs','confirms','feedback'].map(async name=>(await getDocs(collection(db,'portal_public',accessToken,name))).docs.map(d=>({...d.data(),id:d.id,collection:name}))));return groups.flat();}
async function rotateLink(){const c=clone(client()),old=c.accessToken,records=await allRecords(old);const nextToken=newToken();const ops=records.flatMap(({id,collection:col,...data})=>[{token:nextToken,path:[col,id],data},{token:old,path:[col,id],delete:true}]);ops.push({token:old,path:[],delete:true});c.accessToken=nextToken;await saveClient(c,'Private link replaced. Copy and share the new link.',ops);finishModal();}
async function purgeClient(key){const c=state.clients[key];if(!c?._deleted)throw new Error('Move the client to the recycle bin first.');const records=await allRecords(c.accessToken);for(let offset=0;offset<records.length;offset+=400){const batch=writeBatch(db);for(const r of records.slice(offset,offset+400))batch.delete(doc(db,'portal_public',c.accessToken,r.collection,r.id));await batch.commit();}const batch=writeBatch(db);batch.delete(doc(db,'portal_public',c.accessToken));batch.delete(doc(db,'portal_clients',key));await batch.commit();delete state.clients[key];notify('Client permanently deleted');}
function download(name,content,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportCsv(){const headers=['Number','Breed','Title','Status','Started','Delivered','Duration','Final video','Script','Avatar','Reference','Client note'];const keys=['n','b','t','s','sd','dd','dur','dl','scriptUrl','avatarUrl','referenceUrl','clientNote'];const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download(`${state.projectKey}-deliveries.csv`,'\uFEFF'+[headers,...itemsOf(project()).map(i=>keys.map(k=>i[k]))].map(row=>row.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');notify('Delivery CSV downloaded');}
async function report(){notify('Loading complete report…');const freshRecords=await allRecords(state.mode==='client'?state.token:client().accessToken);state.artifacts[state.clientKey]=Object.fromEntries(['sigs','confirms','feedback'].map(col=>[col,freshRecords.filter(r=>r.collection===col)]));const s=activeSignature(),r=s?sigReview(s):{};const html=buildProjectReport({client:client(),project:project(),items:itemsOf(project()),approvals:project().approvals.map(a=>({...a,confirmation:confirmation(a)})),signature:s?{...s,review:r,displayName:r.displayName||s.name,outdated:signatureOutdated(s,project())}:null,feedback:visibleRequests().map(f=>({...f,...reviewOf(f)})),logoUrl:new URL('../logo.png',location.href).href,pdfLibraryUrl:new URL('./html2pdf.bundle.min.js',location.href).href,exportScriptUrl:new URL('./report-export.js',location.href).href,generatedAt:now()});modal('Project report','Review all details, then use Print / save PDF inside the preview.',`<iframe class="report-frame" title="Printable project report" srcdoc="${esc(html)}"></iframe>`,null);$('modalLayer').querySelector('.modal').classList.add('report-modal');notify('Report ready. No pop-up permission is needed.');}

async function action(name,source){
  if(name==='close-modal')return closeModal();
  if(name==='dashboard'){state.clientKey=null;state.projectKey=null;state.page='workspace';return render();}
  if(name==='trash'){requireAdmin();state.page='trash';return render();}
  if(name==='refresh')return location.reload();
  if(name==='logout'){clearSubscriptions();state.clients={};state.user=null;await signOut(auth);state.mode='login';return render();}
  if(name==='open-client'){state.clientKey=source.dataset.client||state.clientKey;state.projectKey=null;state.tab='overview';state.page='workspace';return render();}
  if(name==='open-project'){state.projectKey=source.dataset.project;state.tab='overview';return render();}
  if(name==='tab-log'||name==='tab-overview'){state.tab=name==='tab-log'?'log':'overview';return render();}
  if(name==='add-client'||name==='edit-client')return openClientForm(name==='edit-client');
  if(name==='add-project'||name==='edit-project')return openProjectForm(name==='edit-project');
  if(name==='edit-item')return openItem(Number(source.dataset.number));
  if(name==='add-payment'||name==='edit-payment')return openPayment(source.dataset.id);
  if(name==='add-approval'||name==='edit-approval')return openApproval(source.dataset.id);
  if(name==='feedback-project'||name==='feedback-item')return openFeedback(Number(source.dataset.number)||0);
  if(name==='review-feedback')return openFeedbackReview(source.dataset.id,source.dataset.collection);
  if(name==='manage-signature')return openSignatureReview(source.dataset.id);
  if(name==='sign')return openSignature();
  if(name==='signed-terms'){const s=projectSigs().find(s=>s.id===source.dataset.id);return modal('Signed project record',`Signed by ${s.name} on ${dateText(s.signedAt)}`,s.termsSnapshot?termsHtml(s.termsSnapshot):'<p>This legacy record did not include a terms snapshot.</p>',null);}
  if(name==='clear-signature'){if(pad){pad.ctx.clearRect(0,0,pad.canvas.width,pad.canvas.height);pad.drawn=false;}return;}
  if(name==='copy-client'||name==='copy-project'){notify('Copying private link…');const url=clientUrl(client(),name==='copy-project'?state.projectKey:null);try{await navigator.clipboard.writeText(url);notify('Private link copied');}catch{modal('Copy private link','Select and copy this link.',field('Private URL','url',url,'text','readonly'),null);}return;}
  if(name==='preview-client'){const win=window.open(clientUrl(client(),state.projectKey),'_blank','noopener');notify('Opening private client view…');return win;}
  if(name==='link-settings')return linkSettings();
  if(name==='archived-rows')return openArchivedRows();
  if(name==='report')return report();
  if(name==='export-csv')return exportCsv();
  if(name==='export-all'){requireAdmin();const fresh={};const records={};for(const d of (await getDocs(collection(db,'portal_clients'))).docs){fresh[d.id]=normalizeClient(d.data(),d.id);records[d.id]=await allRecords(fresh[d.id].accessToken);}download(`vision-flow-backup-${localDay()}.json`,JSON.stringify({exportedAt:now(),version:4,clients:fresh,artifacts:records},null,2),'application/json');return notify('Private backup downloaded, including recycled clients. Keep it secure.');}
  requireAdmin();
  if(name.startsWith('archive-')){if(!confirm('Move this record to the recycle bin? You can restore it later.'))return;await archive(name.slice(8),source);return render();}
  if(name==='restore-client'){const c=clone(state.clients[source.dataset.client]);c._deleted=false;await saveClient(c,'Client restored');return render();}
  if(name==='restore-trash'){await restoreTrash(source.dataset.client,source.dataset.id);return render();}
  if(name==='purge-trash'){if(!confirm('Permanently delete this recycled record? It cannot be restored.'))return;const c=clone(state.clients[source.dataset.client]);delete c.trash[source.dataset.id];await saveClient(c,'Recycled record permanently deleted');return render();}
  if(name==='purge-client'){if(confirm('Permanently delete this client and every project, signature, request and payment? This cannot be undone.'))await purgeClient(source.dataset.client);return render();}
  if(name==='restore-row'||name==='purge-row'){const c=clone(client()),p=c.projects[state.projectKey],number=Number(source.dataset.number),i=p.items.find(i=>Number(i.n)===number);if(!i?.deleted)throw new Error('Archived row not found.');if(name==='purge-row'){if(!confirm('Permanently delete this archived production row?'))return;p.items=p.items.filter(x=>x!==i);}else{delete i.deleted;delete i.deletedAt;}p.totalItems=itemsOf(p).length;await saveClient(c,name==='restore-row'?'Row restored':'Row permanently deleted');finishModal();return;}
  if(name==='reset-approval'){const id=source.dataset.id;if(!confirm('Reset the client confirmation? The approval request will remain available to confirm again.'))return;await saveClient(clone(client()),'Confirmation reset',[{path:['confirms',id],delete:true}]);return render();}
  if(name==='toggle-sharing'){const c=clone(client());c.accessEnabled=c.accessEnabled===false;await saveClient(c,c.accessEnabled?'Sharing enabled':'Sharing paused');return finishModal();}
  if(name==='rotate-link'){if(confirm('Replace the private link? The old link will stop working.'))await rotateLink();return;}
}
document.addEventListener('click',event=>{const source=event.target.closest('[data-action]');if(!source||state.busy)return;const name=source.dataset.action;
  if(name==='confirm-approval'){source.disabled=true;source.textContent='Confirming…';setDoc(doc(db,'portal_public',state.token,'confirms',source.dataset.id),{projectKey:state.projectKey,confirmedAt:now(),userAgent:navigator.userAgent}).then(()=>notify('Update confirmed')).catch(fail).finally(()=>{source.disabled=false;source.textContent='Confirm update';});return;}
  const old=source.textContent;let result;try{result=action(name,source);}catch(error){fail(error);return;}if(result?.then){source.disabled=true;source.textContent='Working…';result.catch(fail).finally(()=>{source.disabled=false;source.textContent=old;render();});}
});
document.addEventListener('submit',async event=>{if(event.target.id!=='loginForm')return;event.preventDefault();const form=event.target,send=form.querySelector('[type=submit]'),data=new FormData(form);send.disabled=true;send.textContent='Signing in…';try{await signInWithEmailAndPassword(auth,text(data.get('email')),String(data.get('password')));}catch(error){form.querySelector('.form-error').textContent=errorMessage(error);fail(error);}finally{send.disabled=false;send.textContent='Sign in securely';}});
document.addEventListener('input',e=>{if(e.target.id==='itemSearch')state.filter=e.target.value;else if(e.target.id==='itemStatus')state.status=e.target.value;else if(e.target.id==='itemBatch')state.batch=e.target.value;else return;applyFilters();});
document.addEventListener('change',e=>{if(e.target.name!=='proof')return;const file=e.target.files[0];if(!file)return;if(previewObjectUrl)URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=URL.createObjectURL(file);$('proofPreview').src=previewObjectUrl;$('proofPreview').classList.add('visible');});
$('modalLayer').addEventListener('click',event=>{if(event.target===$('modalLayer'))closeModal();});
document.addEventListener('keydown',event=>{if($('modalLayer').hidden)return;if(event.key==='Escape'){event.preventDefault();closeModal();}if(event.key==='Tab'){const nodes=[...$('modalLayer').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')].filter(x=>!x.hidden);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
const access=new URLSearchParams(location.search).get('access');
if(access)startClient(access);else onAuthStateChanged(auth,async user=>{state.user=user;if(!user){clearSubscriptions();state.mode='login';render();return;}if(user.uid!==ADMIN_UID){await signOut(auth);state.mode='login';renderLogin('This account does not have administrator access.');return;}startAdmin();});
setTimeout(()=>{if(!state.loaded&&!['login','error'].includes(state.mode)){$('view').innerHTML=empty('Taking longer than expected','Check your connection and try again.')+button('Retry','refresh');}},15000);
